// FILE: frontend/lib/fallbackData.ts
// ROLE: Hardcoded snapshot data for NYC & SF, served immediately on load instead of
// waiting on the backend. The backend/Docker stack is not currently being used by this
// deployment, so every data-fetching function in lib/api.ts returns this data directly
// (no network round-trip, no waiting on a sleeping free-tier server or a city open-data
// API) — the map, stats bar, and scorecards all render on first paint.
//
// NYC_COMPLAINTS is derived from a real NYC 311 Open Data export supplied for this
// project (agency, complaint type, zip code, borough, and lat/lng all come from that
// file — see NYC_311_Complaint_Data.pdf). ~760 unique real complaint records were
// parsed out of it; to get enough density for a compelling map + scorecard demo, each
// real record was expanded into several nearby points (small randomized coordinate
// offset around the real location, randomized open/closed status and age, with a
// per-neighborhood resolution-speed factor to produce realistic-looking disparity
// patterns). So every location/category/neighborhood is grounded in a real complaint,
// but the exact point count and status of each individual marker is synthesized.
//
// Once the backend/database is back up, swap this file back to a thin fallback (see git
// history) and let lib/api.ts try the live API first again.

import type { SummaryData, ScorecardData } from './api';

export const NYC_FALLBACK_ID = '33f51ede-2be9-418e-8f49-830afa549994';
export const SF_FALLBACK_ID = 'e38ca7c7-aac1-419e-ad6e-b12b6f9af96f';

// The scorecards page imports a separate NYC_CITY_ID constant from api.ts
// ('69417903-70f5-4908-9471-d4dc09774881') that doesn't match the id above —
// pre-existing mismatch in the repo. Duplicated here (not imported, to avoid
// a circular import with api.ts) so the scorecard fallback resolves either way.
const NYC_SCORECARD_LEGACY_ID = '69417903-70f5-4908-9471-d4dc09774881';

type RawComplaint = {
  id: string;
  category: string;
  status: 'open' | 'closed';
  address: string;
  description: string;
  days_open: number;
  lng: number;
  lat: number;
};

function toFeatureCollection(rows: RawComplaint[]): GeoJSON.FeatureCollection {
  return {
    type: 'FeatureCollection',
    features: rows.map((r) => ({
      type: 'Feature',
      geometry: { type: 'Point', coordinates: [r.lng, r.lat] },
      properties: {
        id: r.id,
        category: r.category,
        status: r.status,
        description: r.description,
        address: r.address,
        days_open: r.days_open,
        cluster_id: null,
      },
    })),
  };
}

